vices as$d):?><article class="comm-row"><p>Device <?=e(substr($d['id'],0,8))?> · <?=e($d['last_status'])?></p><button class="wbtn" type="button" data-remove-device="<?=e($d['id'])?>">Remove device</button></article><?php endforeach;?></section></div>
